import{_ as t,o as a,c as n,a2 as s}from"./chunks/framework.Dt6pBwm7.js";const u=JSON.parse('{"title":"Table + Gantt 101","description":"","frontmatter":{},"headers":[],"relativePath":"tutorial/index.md","filePath":"tutorial/index.md"}'),d={name:"tutorial/index.md"};function o(l,e,i,r,c,p){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="table-gantt-101" tabindex="-1">Table + Gantt 101 <a class="header-anchor" href="#table-gantt-101" aria-label="Permalink to &quot;Table + Gantt 101&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Anonymized documentation</p><p>Company names, package names, custom-element tags, and URLs are placeholders throughout this guide, including imported code. Map them back to the real private dependencies before running examples. The application source has not been renamed.</p></div><p>This walkthrough explains how the implementation merged in PR #7 works and how to reproduce it in this starter kit. You do not need to know TanStack, custom elements, or the layout system before starting. Basic JavaScript and JSX will help.</p><div class="tip custom-block"><p class="custom-block-title">Already using this checkout?</p><p>The application code below is already installed in the repository. Read it and run the checkpoints; <strong>do not paste second copies of registrations, modules, or config entries</strong>. When adapting another application, merge the relevant entries into its existing files instead of replacing its entire configuration.</p></div><h2 id="what-you-will-build" tabindex="-1">What you will build <a class="header-anchor" href="#what-you-will-build" aria-label="Permalink to &quot;What you will build&quot;">​</a></h2><ul><li>Two independent application modules: a TanStack v9 table and a v8 comparison.</li><li>Each table nested inside a real <code>lc-gantt</code> custom element.</li><li>A timeline column with <strong>Summary, BinPoint, Timeline, and FocusPointer in its header</strong>, not above the whole table.</li><li>Date ranges, milestone images, grid lines, and mouse actions in visible rows.</li><li>A 7/14/30/60/90-day selector and a button that replaces mock snapshots.</li><li>A separator that changes the modules&#39; relative widths between 25% and 75%.</li><li>A timeline column that fills remaining space and repaints on resize.</li><li>Fixed-height windowing so thousands of records do not create thousands of continuously rendering canvases.</li></ul><h2 id="first-understand-the-three-boundaries" tabindex="-1">First understand the three boundaries <a class="header-anchor" href="#first-understand-the-three-boundaries" aria-label="Permalink to &quot;First understand the three boundaries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Boundary</th><th>Responsibility</th><th>Not responsible for</th></tr></thead><tbody><tr><td>TanStack Table v9</td><td>Records, columns, stable IDs, sorting, row model</td><td>Canvas drawing or module layout</td></tr><tr><td><code>@lc/graphs</code></td><td>Custom elements, date-to-pixel scales, canvas drawing, chart events</td><td>Sorting the application&#39;s records</td></tr><tr><td>Application layout</td><td>Creates modules, arranges the panels, handles the width separator</td><td>Computing dates or table rows</td></tr></tbody></table><p>The package name is <strong><code>@lc/graphs</code></strong> (plural), not <code>@lc/graph</code>. <code>Gantt</code> is an exported <strong>custom-element constructor</strong>, not a React component. After registration, JSX renders <code>&lt;lc-gantt&gt;</code>, not <code>&lt;Gantt /&gt;</code>.</p><h2 id="see-the-finished-structure" tabindex="-1">See the finished structure <a class="header-anchor" href="#see-the-finished-structure" aria-label="Permalink to &quot;See the finished structure&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TableDemo (one instance per module)</span></span>
<span class="line"><span>  single-row toolbar: title | Rows + Refresh | Visible days + feedback</span></span>
<span class="line"><span>  GanttDemo</span></span>
<span class="line"><span>    lc-gantt.gantt-demo             &lt;- real outer table wrapper</span></span>
<span class="line"><span>      React GanttContext.Provider</span></span>
<span class="line"><span>        .ds-table-scroll</span></span>
<span class="line"><span>          table</span></span>
<span class="line"><span>            thead</span></span>
<span class="line"><span>              tr</span></span>
<span class="line"><span>                th: ID</span></span>
<span class="line"><span>                th: Asset</span></span>
<span class="line"><span>                th: Status</span></span>
<span class="line"><span>                th: Amount</span></span>
<span class="line"><span>                th: GanttHeader</span></span>
<span class="line"><span>                  lc-gantt.gantt-header</span></span>
<span class="line"><span>                    lc-gantt-summary</span></span>
<span class="line"><span>                      lc-gantt-bin-point</span></span>
<span class="line"><span>                      lc-gantt-mouse-events</span></span>
<span class="line"><span>                        lc-gantt-mouse-events-set-action</span></span>
<span class="line"><span>                    lc-gantt-timeline</span></span>
<span class="line"><span>                      lc-graph-label-element</span></span>
<span class="line"><span>                    lc-gantt-focus-pointer</span></span>
<span class="line"><span>            tbody</span></span>
<span class="line"><span>              spacer row (when needed)</span></span>
<span class="line"><span>              visible data rows</span></span>
<span class="line"><span>                td: GanttCell</span></span>
<span class="line"><span>                  lc-gantt.gantt-cell</span></span>
<span class="line"><span>                    lc-gantt-row</span></span>
<span class="line"><span>                      lc-gantt-date-range</span></span>
<span class="line"><span>                      lc-gantt-date-point</span></span>
<span class="line"><span>                        lc-graph-image-element</span></span>
<span class="line"><span>                      lc-gantt-column-divider</span></span>
<span class="line"><span>                      lc-gantt-mouse-events</span></span>
<span class="line"><span>                        lc-gantt-mouse-events-set-action</span></span>
<span class="line"><span>              spacer row (when needed)</span></span></code></pre></div><p>Why several <code>lc-gantt</code> elements? The header and cells need scales based on the <strong>timeline column&#39;s width</strong>, not the entire table&#39;s width. Separate charts share the same date domain and width. Putting one full-width axis above the table would include the ID/name/status columns in the scale and misalign dates.</p><h2 id="file-map" tabindex="-1">File map <a class="header-anchor" href="#file-map" aria-label="Permalink to &quot;File map&quot;">​</a></h2><p>All paths below are relative to the repository root.</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th><th>Chapter</th></tr></thead><tbody><tr><td><code>package.json</code></td><td>Workspaces and validation/documentation commands</td><td>1</td></tr><tr><td><code>app/package.json</code></td><td>Application&#39;s lc and module dependencies</td><td>1, 4</td></tr><tr><td><code>packages/design-system/table/package.json</code></td><td>Isolated v9 engine dependency</td><td>2</td></tr><tr><td><code>packages/design-system/table/src/index.tsx</code></td><td>v9 React table renderer</td><td>2</td></tr><tr><td><code>packages/design-system/src/useTableWindow.ts</code></td><td>Shared fixed-height row window</td><td>2</td></tr><tr><td><code>app/src/index.define.ts</code></td><td>Custom-element registrations</td><td>3</td></tr><tr><td><code>app/src/types/index.ts</code></td><td>Declarations for untyped lc packages</td><td>3</td></tr><tr><td><code>modules/module-table-v8/src/gantt.tsx</code></td><td>Shared Gantt types, wrapper, header, cells</td><td>3</td></tr><tr><td><code>modules/module-table-v8/src/demo.tsx</code></td><td>Mock snapshots, controls, timing</td><td>4</td></tr><tr><td><code>modules/module-table/src/module.index.tsx</code></td><td>v9 module and column definitions</td><td>4</td></tr><tr><td><code>modules/module-table-v8/src/module.index.tsx</code></td><td>v8 comparison module</td><td>4</td></tr><tr><td><code>app/src/moduleLoader.ts</code></td><td>Loads module packages</td><td>4</td></tr><tr><td><code>app/static/configs/general.json</code></td><td>Named layout containers and resizable flag</td><td>5</td></tr><tr><td><code>app/static/configs/modules.json</code></td><td>Which modules start in each container</td><td>5</td></tr><tr><td><code>app/src/components/Layout/Layout.jsx</code></td><td>Passes layout options to Panel</td><td>5</td></tr><tr><td><code>app/src/components/Layout/Panel.jsx</code></td><td>Separator events and split state</td><td>5</td></tr><tr><td><code>app/src/components/App.css</code></td><td>Panel/divider and mobile styles</td><td>5</td></tr><tr><td><code>packages/design-system/src/table.css</code></td><td>Basic table, scroll, and control styles</td><td>6</td></tr><tr><td><code>modules/module-table-v8/src/gantt.css</code></td><td>Timeline column and toolbar sizing</td><td>6</td></tr><tr><td><code>tools/measure-table-runtime.mjs</code></td><td>Browser checks for actual behavior</td><td>7</td></tr></tbody></table><p>The shared demo happens to live under the v8 module. It imports <strong>neither engine</strong>, so both modules can reuse it without mixing TanStack major versions. Moving it into another package is not required for this exercise.</p><h2 id="read-in-order" tabindex="-1">Read in order <a class="header-anchor" href="#read-in-order" aria-label="Permalink to &quot;Read in order&quot;">​</a></h2><ol><li><a href="./01-setup">Install and run</a>.</li><li><a href="./02-table-v9">Build the v9 table</a>.</li><li><a href="./03-gantt">Register and compose Gantt</a>.</li><li><a href="./04-modules">Wire mock data and modules</a>.</li><li><a href="./05-resizing">Configure two modules and their draggable separator</a>.</li><li><a href="./06-widths">Make the timeline fill available width</a>.</li><li><a href="./07-validation">Verify behavior and troubleshoot</a>.</li></ol><h2 id="how-to-use-the-code-blocks" tabindex="-1">How to use the code blocks <a class="header-anchor" href="#how-to-use-the-code-blocks" aria-label="Permalink to &quot;How to use the code blocks&quot;">​</a></h2><p>Small blocks explain one idea. Blocks marked <strong>complete source</strong> are imported directly from the implementation at documentation build time. They include imports and cleanup, not just fragments. Keep the shown file locations when copying: their relative imports depend on that structure.</p><p>The documentation site displays code; it does not execute the React app or register its browser-only custom elements during server-side rendering. Run the application separately with <code>yarn dev</code> to interact with the demo.</p>`,21)])])}const m=t(d,[["render",o]]);export{u as __pageData,m as default};
